<?php
namespace App\Services;use App\Models\{Committee,CommitteeScheduleItem};use Carbon\Carbon;use Illuminate\Support\Facades\DB;use Illuminate\Validation\ValidationException;
class CommitteeScheduleService{public function __construct(private CommitteeRegulationService $rules,private CommitteeOperationService $operations){}public function generateBase(Committee $committee,array $data,int $userId):int{$this->operations->ensureActive($committee);return DB::transaction(function()use($committee,$data,$userId){$formation=$committee->latestFinalFormation;$start=max(Carbon::parse($data['start_date'])->startOfMonth(),$formation->effective_from->copy()->startOfMonth());$end=min(Carbon::parse($data['end_date'])->endOfMonth(),$formation->effective_to->copy()->endOfMonth());$count=0;for($month=$start->copy();$month->lte($end);$month->addMonthsNoOverflow($this->rules->meetingFrequencyMonths($committee->type))){$date=$month->copy()->nthOfMonth((int)$data['weekday'],(int)$data['occurrence']);if($date->lt($formation->effective_from)||$date->gt($formation->effective_to))continue;$exists=$committee->scheduleItems()->where('activity_type','ordinary_meeting')->whereYear('scheduled_date',$date->year)->whereMonth('scheduled_date',$date->month)->exists();if(!$exists){$committee->scheduleItems()->create(['committee_period_id'=>$formation->committee_period_id,'activity_type'=>'ordinary_meeting','title'=>'Reunión ordinaria '.$committee->name,'description'=>'Reunión administrativa ordinaria mensual','scheduled_date'=>$date,'start_time'=>$data['start_time'],'location'=>$data['location']??null,'modality'=>$data['modality'],'phva_stage'=>'H','status'=>'scheduled','regulation_reference'=>$this->rules->meetingReference($committee->type),'created_by'=>$userId,'updated_by'=>$userId]);$count++;}}$this->operations->audit($committee,'schedule_generated',$committee,$userId,['items'=>$count,'start'=>$start->toDateString(),'end'=>$end->toDateString()]);return$count;});}public function create(Committee $committee,array $data,int $userId):CommitteeScheduleItem{$this->operations->ensureActive($committee);$formation=$committee->latestFinalFormation;if(Carbon::parse($data['scheduled_date'])->lt($formation->effective_from)||Carbon::parse($data['scheduled_date'])->gt($formation->effective_to))throw ValidationException::withMessages(['scheduled_date'=>'La actividad debe quedar dentro de la vigencia del comité.']);$item=$committee->scheduleItems()->create(array_merge($data,['committee_period_id'=>$formation->committee_period_id,'status'=>'scheduled','created_by'=>$userId,'updated_by'=>$userId]));$this->operations->audit($committee,'activity_created',$item,$userId);return$item;}public function reschedule(CommitteeScheduleItem $item,string $date,string $reason,int $userId):void{$this->operations->ensureActive($item->committee);$new=Carbon::parse($date);if($new->lt($item->period->start_date)||$new->gt($item->period->end_date))throw ValidationException::withMessages(['new_date'=>'La nueva fecha está fuera de la vigencia.']);DB::transaction(function()use($item,$new,$reason,$userId){$item->changes()->create(['original_date'=>$item->scheduled_date,'new_date'=>$new,'change_type'=>'rescheduled','reason'=>$reason,'changed_by'=>$userId,'changed_at'=>now()]);$item->update(['scheduled_date'=>$new,'status'=>'rescheduled','updated_by'=>$userId]);$this->operations->audit($item->committee,'activity_rescheduled',$item,$userId,['reason'=>$reason]);});}public function cancel(CommitteeScheduleItem $item,string $reason,int $userId):void{$this->operations->ensureActive($item->committee);DB::transaction(function()use($item,$reason,$userId){$item->changes()->create(['original_date'=>$item->scheduled_date,'change_type'=>'cancelled','reason'=>$reason,'changed_by'=>$userId,'changed_at'=>now()]);$item->update(['status'=>'cancelled','updated_by'=>$userId]);$this->operations->audit($item->committee,'activity_cancelled',$item,$userId,['reason'=>$reason]);});}}
